/** Code tokens that are not in the English lists. */
const EXTRA_HUMP_WORDS = `
aes ansible args argv async atob batchnorm bcrypt bigquery btoa canonicalizer checksum ciphertext clickhouse configmap containerd cronjob csrf cuda dataloader debounce deserializer dirname dockerfile dotnet dtype ecdsa elasticsearch embedding esbuild eslint extname fastapi fastlane firebase firestore gradle grafana graphql grpc helmfile hmac hostname idempotent initializer jwt keystore kubeconfig kubectl kubelet kubernetes kustomize linq localhost marshaller maven middleware minikube mutex nginx nuget numpy nunit oauth oidc opensearch openssl optimizer passphrase pathname plaintext postgres prefetch prisma protobuf pydantic redis redshift regex rollup rsa runtimeclass sequelize serializer serilog sinon sklearn softmax sqlalchemy stdin stdout stylelint substring supabase tensor terraform tokenizer typeorm unmarshaller uuid vitest webhook webpack whitespace wildcard xunit
encode rollout cohort upsert retry jitter limiter iterable enumerable lifecycle nullable multipart refactor unicode iterator parse serialize deserialize stringify jsonify encrypt logout signin sanitize unescape normalize canonicalize truncate append prepend concat dedupe memoize invalidate dehydrate unmount resize keydown keyup deselect toggle unmute reindex prettify histogram exporter validator parser lexer bytecode opcode operand deque trie quantile latency throughput frontend backend endpoint timestamp filesystem readonly
`;

function loadHumpWords(): Set<string> {
  const text = inflateSync(Buffer.from(PACKED_HUMP_WORDS, 'base64')).toString('utf8');
  const words = new Set<string>();
  let start = 0;
  for (let i = 0; i <= text.length; i += 1) {
    if (i === text.length || text.charCodeAt(i) === 10) {
      if (i > start) words.add(text.slice(start, i));
      start = i + 1;
    }
  }
  const extra = EXTRA_HUMP_WORDS.trim().split(/\s+/);
  for (let i = 0; i < extra.length; i += 1) words.add(extra[i]);
  return words;
}

const HUMP_WORDS: ReadonlySet<string> = loadHumpWords();

/**
 * True when [from, to) is a dictionary word, ignoring a leading capital.
 * One pass. The span is at most 16 letters.
 */
export function humpWordAt(line: string, from: number, to: number): boolean {
  const n = to - from;
  if (n < 2 || n > 16) return false;
  let lower = '';
  for (let i = from; i < to; i += 1) {
    const code = line.charCodeAt(i);
    if (code >= 97 && code <= 122) lower += String.fromCharCode(code);
    else if (code >= 65 && code <= 90) lower += String.fromCharCode(code + 32);
    else return false;
  }
  return HUMP_WORDS.has(lower);
}
